-- ============================================
-- LUMA — Nouveau scénario long : De serveur à barman (Australie)
-- ============================================

with th as (select id from scenario_themes where position = 16 and language_id = (select id from languages where code = 'en'))
insert into scenarios (theme_id, format, cecr_level, title, content, is_playable)
select th.id, 'long', 'B1-B2', 'Un mois de travail : de serveur à barman', '{"characters": {"kate": "Kate (gérante)", "ryan": "Ryan (barman senior)"}, "start_node": "n1", "nodes": {"n1": {"speaker": "kate", "text": "Welcome aboard! You''ll start on floor service — taking orders, running food, clearing tables.", "text_fr": "Bienvenue dans l''équipe ! Tu commences en salle — prendre les commandes, apporter les plats, débarrasser.", "choices": [{"text": "Sounds good, I''m ready to learn the ropes.", "next": "n2"}, {"text": "Is there a chance to move behind the bar eventually?", "next": "n2b"}]}, "n2": {"speaker": "kate", "text": "Great attitude. Ryan here will show you the floor tonight.", "text_fr": "Super attitude. Ryan va te montrer la salle ce soir.", "choices": [{"text": "Looking forward to it.", "next": "n3"}]}, "n2b": {"speaker": "kate", "text": "Absolutely, if you show initiative, we move people up fast here.", "text_fr": "Tout à fait, si tu montres de l''initiative, on fait évoluer les gens vite ici.", "choices": [{"text": "Then I''ll make sure to stand out.", "next": "n3"}]}, "n3": {"speaker": "ryan", "text": "(week 1) Busy Friday night — think you can keep up with the pace?", "text_fr": "(semaine 1) Vendredi soir chargé — tu penses pouvoir suivre le rythme ?", "choices": [{"text": "I''ll do my best, just point me in the right direction.", "next": "n4"}, {"text": "Honestly, it''s a lot, but I won''t give up.", "next": "n4b"}]}, "n4": {"speaker": "ryan", "text": "That''s the spirit — you handled that rush better than most newbies.", "text_fr": "Voilà l''esprit — tu as géré ce coup de feu mieux que la plupart des débutants.", "choices": [{"text": "Thanks, it was intense but I loved it.", "next": "n5"}]}, "n4b": {"speaker": "ryan", "text": "That''s exactly the mindset you need here. Rough nights happen to everyone.", "text_fr": "C''est exactement l''état d''esprit qu''il faut ici. Les soirées difficiles arrivent à tout le monde.", "choices": [{"text": "Good to know, I''ll keep pushing through.", "next": "n5"}]}, "n5": {"speaker": "kate", "text": "(week 2) You''ve been solid on the floor. Want to start learning the bar basics?", "text_fr": "(semaine 2) Tu as été solide en salle. Tu veux commencer à apprendre les bases du bar ?", "choices": [{"text": "Absolutely, I''ve been hoping you''d ask.", "next": "n6"}]}, "n6": {"speaker": "ryan", "text": "Let''s start simple — pouring beers and basic mixed drinks.", "text_fr": "Commençons simple — servir des bières et des cocktails de base.", "choices": [{"text": "Show me the pour technique, I want to get it right.", "next": "n7"}, {"text": "I''ve actually watched a few tutorials already, want to try?", "next": "n7b"}]}, "n7": {"speaker": "ryan", "text": "Good instinct asking — tilt the glass, pour slow, straighten at the end.", "text_fr": "Bon réflexe de demander — incline le verre, verse doucement, redresse à la fin.", "choices": [{"text": "(practice pouring carefully, following the technique)", "next": "n8"}]}, "n7b": {"speaker": "ryan", "text": "Not bad at all! A bit heavy on the pour, but good instincts.", "text_fr": "Pas mal du tout ! Un peu trop généreux sur le versement, mais bon instinct.", "choices": [{"text": "I''ll dial it back next time, thanks for the feedback.", "next": "n8"}]}, "n8": {"speaker": "kate", "text": "(week 3) A regular customer is being rude to another staff member. Can you help defuse it?", "text_fr": "(semaine 3) Un client habitué est désagréable avec un autre membre du personnel. Tu peux calmer la situation ?", "choices": [{"text": "I''ll step in calmly and offer him a drink on the house.", "next": "n9"}, {"text": "I''ll politely explain our policy and ask him to lower his tone.", "next": "n9b"}]}, "n9": {"speaker": "kate", "text": "Smart move, that diffused things nicely without any conflict.", "text_fr": "Bon réflexe, ça a calmé les choses sans aucun conflit.", "choices": [{"text": "Glad it worked out, teamwork matters here.", "next": "n10"}]}, "n9b": {"speaker": "kate", "text": "Firm but respectful, exactly how we handle it. Well done.", "text_fr": "Ferme mais respectueux, exactement comme on gère ça. Bien joué.", "choices": [{"text": "Thank you, I want to protect the team''s atmosphere.", "next": "n10"}]}, "n10": {"speaker": "ryan", "text": "(week 4) You''ve picked up cocktails fast. Ready to run the bar solo tonight?", "text_fr": "(semaine 4) Tu as vite appris les cocktails. Prêt à tenir le bar seul ce soir ?", "choices": [{"text": "Yes, I feel ready for it, let''s do this.", "next": "end_bartender"}, {"text": "I''d love that, but could you check in on me a few times?", "next": "end_supported"}]}, "end_bartender": {"speaker": "kate", "text": "You crushed it tonight. Officially, you''re our new barman!", "text_fr": "Tu as assuré ce soir. Officiellement, tu es notre nouveau barman !", "end": true, "ending_label": "De serveur à barman en un mois 🍹"}, "end_supported": {"speaker": "ryan", "text": "Of course, I''ll swing by. You''ve earned this role either way.", "text_fr": "Bien sûr, je passerai voir. Tu as mérité ce poste dans tous les cas.", "end": true, "ending_label": "De serveur à barman, en équipe 🍹🤝"}}}'::jsonb, true from th;
